#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTandemAudioSink: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<TandemAudioSink>()

    typealias FfiType = UInt64
    typealias SwiftType = TandemAudioSink

    public static func lift(_ handle: UInt64) throws -> TandemAudioSink {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return TandemAudioSinkImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: TandemAudioSink) -> UInt64 {
         if let rustImpl = value as? TandemAudioSinkImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TandemAudioSink {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: TandemAudioSink, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTandemAudioSink_lift(_ handle: UInt64) throws -> TandemAudioSink {
    return try FfiConverterTypeTandemAudioSink.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTandemAudioSink_lower(_ value: TandemAudioSink) -> UInt64 {
    return FfiConverterTypeTandemAudioSink.lower(value)
}






public protocol TandemEngineProtocol: AnyObject, Sendable {
    
    func acceptOffer(from: String, offer: UInt64) throws 
    
    /**
     * Where a circle member can be reached right now, as `ip:port`. Dials at once.
     */
    func addAddress(id: String, addr: String) throws 
    
    /**
     * How many bytes of samples fit in one packet to this device, 0 when it is not connected.
     */
    func audioPayloadLimit(id: String)  -> UInt32
    
    /**
     * The link named `link` closed: forget what it had half delivered.
     */
    func bleDropLink(link: String) 
    
    /**
     * The first writes to send on a new link, so the other end learns who this is.
     */
    func bleHello(id: String, chunkSize: UInt32)  -> [Data]
    
    /**
     * Whether this computer is the one that looks for `id` over Bluetooth and connects to it, when both are computers: the one with the
     * lower id, which is also the one that makes the key. The other advertises and waits, so there is one link and not two.
     */
    func bleIsCentralFor(id: String)  -> Bool
    
    /**
     * The link to `id` closed.
     */
    func bleLinkDown(id: String) 
    
    /**
     * True once this device and `id` share the key that seals Bluetooth frames. It is
     * made when they first connect over the network.
     */
    func bleReady(id: String)  -> Bool
    
    /**
     * One write that arrived on the link `link` (any stable name for it, such as the
     * Bluetooth address). Returns the device id once a whole message from a circle member
     * has arrived and been handled, which also marks that device as reachable over this link.
     */
    func bleReceive(link: String, chunk: Data) async  -> String?
    
    /**
     * The writes waiting for `id`, each at most `chunk_size` bytes, oldest first. Empty
     * when nothing waits. Call it on a timer while a link is up.
     */
    func bleTakeOutbox(id: String, chunkSize: UInt32)  -> [Data]
    
    func callAction(target: String, id: String, action: TandemCallAction) async throws 
    
    func cancelCapture(target: String, id: UInt64, why: TandemCaptureWhy) async throws 
    
    func cancelPairingOffer() 
    
    /**
     * Stops a transfer that is running: the files in the making are dropped and the other device is told. `incoming` is whether this
     * device is the one receiving it.
     */
    func cancelTransfer(peer: String, offer: UInt64, incoming: Bool) async throws 
    
    /**
     * Back to the default for this device.
     */
    func clearFilePolicy(id: String) throws 
    
    /**
     * Back to the default for this device.
     */
    func clearMediaPolicy(id: String) throws 
    
    func clipboardChanged(text: String, isUrl: Bool) async 
    
    func createPairingOffer() throws  -> TandemPairingOffer
    
    func declineOffer(from: String, offer: UInt64) async throws 
    
    /**
     * The addresses this device was seen at (no port), the likeliest first.
     */
    func deviceIps(id: String)  -> [String]
    
    func devices()  -> [TandemDevice]
    
    func dial(target: String, number: String) async throws 
    
    /**
     * What other devices did to the files here, newest first.
     */
    func fileActivity()  -> [TandemFileActivity]
    
    func fileDefaultPolicy()  -> TandemFilePolicy
    
    func filePolicy(id: String) throws  -> TandemFilePolicy
    
    /**
     * The Focus of this device as the app reads it now, and its name when the system tells. Call it at start and whenever it may
     * have changed, also after following another device: the core works out what is news for the others.
     */
    func focusLocal(on: Bool, name: String) async 
    
    /**
     * A file of the other device to `to`, a path on this one. What an earlier try left as `to.tandem-part` is carried on.
     */
    func fsDownload(id: String, path: String, to: String, progress: TandemFsProgress?) async throws 
    
    func fsList(id: String, path: String) async throws  -> [TandemFsEntry]
    
    func fsMkdir(id: String, path: String) async throws 
    
    /**
     * Part of a file, in memory. At most 64 MiB; for more, download it.
     */
    func fsRead(id: String, path: String, offset: UInt64, len: UInt64) async throws  -> Data
    
    func fsRemove(id: String, path: String, recursive: Bool) async throws 
    
    func fsRename(id: String, from: String, to: String, overwrite: Bool) async throws 
    
    func fsRoots(id: String) async throws  -> [TandemFsRoot]
    
    func fsStat(id: String, path: String) async throws  -> TandemFsEntry
    
    /**
     * A file on this device, a path, to the other device.
     */
    func fsUpload(id: String, from: String, path: String, overwrite: Bool, progress: TandemFsProgress?) async throws 
    
    /**
     * Whether a device that comes into the circle starts as a guest: clipboard and notifications off, files asked about first.
     */
    func guestsByDefault()  -> Bool
    
    /**
     * Whether the device has choices of its own, or is on the default.
     */
    func hasOwnFilePolicy(id: String)  -> Bool
    
    /**
     * Whether the device has choices of its own, or is on the default.
     */
    func hasOwnMediaPolicy(id: String)  -> Bool
    
    func id()  -> String
    
    func isConnected(id: String)  -> Bool
    
    func isMember()  -> Bool
    
    /**
     * Asks `target` to keep itself awake, or to let it sleep again.
     */
    func keepAwake(target: String, on: Bool) async throws 
    
    /**
     * The host app agrees. Frames may be pushed from now on; the first one must be a keyframe.
     */
    func mediaAccept(session: UInt64, answer: TandemMediaAccept) throws 
    
    func mediaDefaultPolicy()  -> TandemMediaPolicy
    
    func mediaDeny(session: UInt64, reason: TandemMediaEnd) throws 
    
    /**
     * Tells a device that this one is ready to show its screen or camera and would like it to look. The other app
     * answers with `media_request`; nothing starts by itself.
     */
    func mediaOffer(peer: String, kind: TandemMediaKind, facing: TandemMediaFacing, extend: Bool) throws 
    
    func mediaPolicy(id: String) throws  -> TandemMediaPolicy
    
    /**
     * Parameter sets the encoder gave apart from its frames (SPS and PPS, and VPS for HEVC), in Annex B. They are put
     * in front of every keyframe that comes without them.
     */
    func mediaPushConfig(session: UInt64, data: Data) throws 
    
    /**
     * An encoded frame: one access unit in Annex B. Never waits for the network; the answer says what became of it.
     */
    func mediaPushFrame(session: UInt64, data: Data, ptsUs: UInt64, keyframe: Bool)  -> TandemMediaPush
    
    /**
     * Asks a device for its screen or camera. Returns the session id at once; the answer arrives through
     * `TandemMediaViewer.on_accepted` or `on_ended`.
     */
    func mediaRequest(peer: String, want: TandemMediaWant) throws  -> UInt64
    
    /**
     * The decoder choked: ask the host for a keyframe.
     */
    func mediaRequestKeyframe(session: UInt64) throws 
    
    /**
     * The viewer of an extra screen was turned: asks the host for the screen in this shape. Only for a host that says
     * `screen.extend.turn`; the new picture is announced with `TandemMediaViewer.on_update`.
     */
    func mediaResize(session: UInt64, resize: TandemMediaResize) throws 
    
    /**
     * Input for the host. Fails when control was not granted.
     */
    func mediaSendInput(session: UInt64, input: TandemMediaInput) throws 
    
    func mediaSessions()  -> [TandemMediaSession]
    
    func mediaStats(session: UInt64)  -> TandemMediaStats?
    
    /**
     * Ends a session from either side. The other side is told.
     */
    func mediaStop(session: UInt64) throws 
    
    /**
     * The picture changed shape, or control is granted or taken away. Call it before the first frame of the new size;
     * that frame must be a keyframe.
     */
    func mediaUpdate(session: UInt64, update: TandemMediaUpdate) throws 
    
    func name()  -> String
    
    /**
     * Call when Wi-Fi, mobile data or the VPN changed.
     */
    func networkChanged() 
    
    func notificationAction(target: String, key: String, button: String, reply: String?, dismiss: Bool) async throws 
    
    /**
     * Asks a device to open a page of its settings, one it named in its features.
     */
    func openSettingsOn(target: String, page: String) async throws 
    
    /**
     * Pairs with the device that shows this: the link of its QR code or the eight digits of its short code.
     */
    func pairWithUri(uri: String) async throws  -> String
    
    func port()  -> UInt16
    
    func removeDevice(id: String) async throws 
    
    func removeNotification(targets: [String], key: String) async throws  -> [String]
    
    func renameSelf(name: String) async throws 
    
    /**
     * Asks a computer to play this phone's sound as its Bluetooth speaker, or to stop. `name` is this phone's Bluetooth name.
     */
    func requestBtSpeaker(target: String, on: Bool, name: String) async throws 
    
    /**
