     * at once instead of waiting.
     */
    func requestCapture(target: String, id: UInt64, kind: TandemCaptureKind) async throws 
    
    /**
     * Asks a phone to be this computer's microphone, or to stop.
     */
    func requestMic(target: String, on: Bool) async throws 
    
    /**
     * Asks the device whose screen this one looks at for its sound, or to stop it.
     */
    func requestSound(target: String, on: Bool) async throws 
    
    func ring(target: String, on: Bool) async throws 
    
    /**
     * This device plays its sound because of `Ring` (`on`), or stopped: the devices that asked are told.
     */
    func ringing(on: Bool) async 
    
    func sendAppIcon(targets: [String], appId: String, png: Data) async throws  -> [String]
    
    /**
     * Sends one packet of sound without waiting. Packets that get lost stay lost.
     */
    func sendAudio(target: String, stream: UInt8, seq: UInt32, pcm: Data) throws 
    
    func sendAudioStart(target: String, stream: UInt8, sampleRate: UInt32, channels: UInt8) async throws 
    
    func sendAudioStop(target: String, stream: UInt8) async throws 
    
    /**
     * Tells a phone whether this computer plays its sound over Bluetooth now, and why not.
     */
    func sendBtSpeakerState(target: String, on: Bool, error: String) async throws 
    
    func sendBytes(targets: [String], name: String, mime: String, data: Data, origin: TandemShareOrigin) async throws  -> TandemSendReport
    
    func sendCall(targets: [String], call: TandemCall) async throws  -> [String]
    
    func sendClipboard(targets: [String], text: String, isUrl: Bool) async throws  -> [String]
    
    func sendFiles(targets: [String], files: [TandemOutgoingFile], origin: TandemShareOrigin) async throws  -> TandemSendReport
    
    func sendHotspot(target: String, hotspot: TandemHotspot) async throws 
    
    func sendInput(target: String, input: TandemInput) async throws 
    
    /**
     * A cover for the players' `art` key. Sent once per cover.
     */
    func sendMediaArt(targets: [String], key: UInt64, jpeg: Data) async throws  -> [String]
    
    /**
     * Asks `target` to do something with one of its players.
     */
    func sendMediaCommand(target: String, player: String, action: TandemMediaAction, positionMs: UInt64?) async throws 
    
    /**
     * This device's players, whole list, to the devices that should show them.
     */
    func sendMediaPlayers(targets: [String], players: [TandemMediaPlayer]) async throws  -> [String]
    
    func sendNotification(targets: [String], notification: TandemNotification) async throws  -> [String]
    
    /**
     * Sends a pointer movement without waiting for delivery.
     */
    func sendPointer(id: String, dx: Int16, dy: Int16) throws 
    
    /**
     * Says to another computer what the pointer does: it goes over, it comes back, or it is taken back.
     */
    func sendPointerShare(target: String, msg: TandemPointerShare) async throws 
    
    func sendScroll(id: String, dx: Int16, dy: Int16) throws 
    
    func sendText(targets: [String], text: String, isUrl: Bool, `open`: Bool) async throws  -> [String]
    
    /**
     * Asks for a password, or answers such a question, over the network or over a Bluetooth link.
     */
    func sendWifi(target: String, wifi: TandemWifi) async throws 
    
    /**
