     * from the setting and from what the system lets the app do; say it again when either changes.
     */
    func setFocusSharing(send: Bool, follow: Bool) 
    
    func setGuestsByDefault(on: Bool) throws 
    
    func setMediaDefaultPolicy(policy: TandemMediaPolicy) throws 
    
    /**
