     * anyone can ask: without one, every request is answered with `Unsupported`.
     */
    func setMediaHost(host: TandemMediaHost) 
    
    func setMediaPolicy(id: String, policy: TandemMediaPolicy) throws 
    
    /**
     * Where the frames of the sessions this device asks for go.
     */
    func setMediaViewer(viewer: TandemMediaViewer) 
    
    /**
     * Which Wi-Fi network this computer is on, `None` for none. Call it at the start and whenever it changes; with `wifi.share`
