    /**
     * Signs with this device's identity key. Used for proofs that cannot travel over
     * QUIC, such as the Bluetooth hotspot request.
     */
    func signMessage(message: Data)  -> Data
    
    /**
     * Stops serving the files of a device as a drive.
     */
    func stopServingFilesAsDrive(id: String) 
    
    /**
     * Asks `target` to unlock its screen. The person here showed it is them first (a fingerprint); `target` checks the rest.
     */
    func unlock(target: String) async throws 
    
    func updateStatus(status: TandemStatus) async 
    
    /**
     * True only when `id` is a current circle member and the signature is theirs.
     */
    func verifyMember(id: String, message: Data, signature: Data)  -> Bool
    
    /**
     * What the device heard of the quiet sweeps, as the side it stands on. Surer than `side_result` before it says a side, because what
     * it says moves a screen without asking.
     */
    func sideCheckResult(id: UInt64) async  -> TandemSide
    
    /**
     * Like `side_start`, for a check that nobody asked for: the device listens only when its microphone is free and allowed, and the app
     * plays `tandem_side_quiet_pattern`. An error when the device did not get ready, which counts as not heard.
     */
    func sideCheckStart(target: String) async throws  -> UInt64
    
    /**
     * Whether the device `id` may read and send the messages of this phone. On unless the person turned it off (or it is a guest).
     */
    func messagesAllowed(id: String)  -> Bool
    
    func setMessagesAllowed(id: String, allowed: Bool) throws 
    
    /**
     * Every person with a number in the contacts of the phone `target`, by contact id, for the search of this computer. Only a phone
     * that says `sms.contacts` answers; ask no other, because an older one stays quiet until the wait runs out.
     */
    func smsAllContacts(target: String) async throws  -> [TandemPhoneContact]
    
    /**
     * A page of the whole list of contacts, for `ListContacts`. `more` when there are people after the last one here.
     */
    func smsAnswerContactPage(target: String, req: UInt64, items: [TandemPhoneContact], more: Bool) async throws 
    
    func smsAnswerContacts(target: String, req: UInt64, items: [TandemSmsContact]) async throws 
    
    func smsAnswerConversations(target: String, req: UInt64, items: [TandemSmsConversation], more: Bool) async throws 
    
    func smsAnswerMessages(target: String, req: UInt64, thread: UInt64, items: [TandemSmsMessage], more: Bool) async throws 
    
    func smsAnswerPicture(target: String, req: UInt64, jpeg: Data) async throws 
    
    /**
     * The text was taken for sending (`error` empty), or why not.
     */
    func smsAnswerSent(target: String, req: UInt64, thread: UInt64?, error: String?) async throws 
    
    /**
     * Asks the person on the phone to let this device in, after a refusal (`Off` or `NoPermission`). The phone shows it;
     * there is no answer.
     */
    func smsAskAccess(target: String) async throws 
    
    /**
     * Tells the computers that may read along about messages that are new or changed here, with their conversations as they are
     * now. Returns the devices that got it.
     */
    func smsChanged(conversations: [TandemSmsConversation], messages: [TandemSmsMessage]) async  -> [String]
    
    /**
     * Contacts of the phone whose name or number contains `query`, for a new message.
     */
    func smsContacts(target: String, query: String) async throws  -> [TandemSmsContact]
    
    /**
     * A page of the conversations of the phone `target`, newest first.
     */
    func smsConversations(target: String, before: UInt64, limit: UInt32) async throws  -> TandemSmsConversationPage
    
    /**
     * A page of the messages of one conversation, newest first.
     */
    func smsMessages(target: String, thread: UInt64, before: UInt64, limit: UInt32) async throws  -> TandemSmsMessagePage
    
    /**
     * One picture of an MMS, as a small JPEG.
     */
    func smsPicture(target: String, part: UInt64) async throws  -> Data
    
    func smsRefuse(target: String, req: UInt64, why: TandemSmsRefusal) async throws 
    
    /**
     * Sends `text` from the phone to the numbers in `to`. Returns the conversation it went to, when the phone knows it. The
     * message itself comes as a change, first while it is being sent and again once it is out or failed.
     */
    func smsSend(target: String, to: [String], text: String) async throws  -> UInt64?
    
