    // declare one manually.
    public init(ssid: String, security: TandemWifiSecurity, hidden: Bool, 
        /**
         * The sender cannot hand its password over now (a phone without Shizuku).
         */locked: Bool = false) {
        self.ssid = ssid
        self.security = security
        self.hidden = hidden
        self.locked = locked
    }

    

    
}

