    typealias SwiftType = TandemCallAction

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TandemCallAction {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .answer
        
        case 2: return .reject
        
        case 3: return .silence
        
        case 4: return .hangup
        
        case 5: return .rejectWithMessage(message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .moveToThisDevice
        
        case 7: return .moveBack
        
        case 8: return .muteMic
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TandemCallAction, into buf: inout [UInt8]) {
        switch value {
        
        
        case .answer:
            writeInt(&buf, Int32(1))
        
        
        case .reject:
            writeInt(&buf, Int32(2))
        
        
        case .silence:
            writeInt(&buf, Int32(3))
        
        
        case .hangup:
            writeInt(&buf, Int32(4))
        
        
        case let .rejectWithMessage(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case .moveToThisDevice:
            writeInt(&buf, Int32(6))
        
        
        case .moveBack:
            writeInt(&buf, Int32(7))
        
        
        case .muteMic:
            writeInt(&buf, Int32(8))
        
        }
    }
}


