public 
enum TandemError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Failed(reason: String
    )
    case NotConnected
    case NotTrusted
    case Pairing(reason: String
    )
    /**
     * The other device would not do what was asked with its files. `code` is one of: not_found, denied, disabled,
     * outside, exists, not_empty, not_dir, is_dir, too_large, unsupported, io.
     */
    case Files(code: String, reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension TandemError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTandemError: FfiConverterRustBuffer {
    typealias SwiftType = TandemError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TandemError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Failed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotConnected
        case 3: return .NotTrusted
        case 4: return .Pairing(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Files(
            code: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TandemError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Failed(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NotConnected:
            writeInt(&buf, Int32(2))
        
        
        case .NotTrusted:
            writeInt(&buf, Int32(3))
        
        
        case let .Pairing(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Files(code,reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


