public enum TandemEvent: Equatable, Hashable {
    
    case devicesChanged
    case connected(id: String
    )
    case disconnected(id: String
    )
    /**
     * A device cannot be reached on the local network and is known by a Tailscale address, while Tailscale is off here. The app may turn it on.
     */
    case tailscaleNeeded(id: String
    )
    case paired(id: String
    )
    case circleChanged
    case removedFromCircle
    case clipboard(from: String, text: String, isUrl: Bool
    )
    case shareOffered(from: String, offer: UInt64, origin: TandemShareOrigin, items: [TandemShareItem]
    )
    case shareText(from: String, text: String, isUrl: Bool, `open`: Bool
    )
    case progress(offer: UInt64, index: UInt32, peer: String, incoming: Bool, name: String, done: UInt64, total: UInt64
    )
    case finished(offer: UInt64, index: UInt32, peer: String, incoming: Bool, name: String, size: UInt64, location: String?, error: String?
    )
    case notification(from: String, notification: TandemNotification
    )
    case notificationRemoved(from: String, key: String
    )
    case notificationAction(from: String, key: String, button: String, reply: String?, dismiss: Bool
    )
    case appIcon(from: String, appId: String, png: Data
    )
    case call(from: String, call: TandemCall
    )
    case callAction(from: String, id: String, action: TandemCallAction
    )
    case dial(from: String, number: String
    )
    /**
     * Another device is nearly empty, or full on the charger: for a notification, when the person wants those.
     */
    case batteryAlert(from: String, level: UInt8, full: Bool
    )
    case ring(from: String, on: Bool
    )
    case keepAwake(from: String, on: Bool
    )
    case unlock(from: String
    )
    /**
     * `quiet` when the other device checks by itself: listen only when the microphone is free and allowed, without asking for it.
     */
    case sideListen(from: String, id: UInt64, quiet: Bool
    )
    /**
     * The answers of a device to `side_start`, which reads them itself: the apps can let them go by.
     */
    case sideReady(from: String, id: UInt64
    )
    case sideHeard(from: String, id: UInt64
    )
    /**
     * The device was moved: find its side again if it matters (a second screen, the shared mouse).
     */
    case sideMoved(from: String
    )
    /**
     * Another device asks to open this page of the settings here (one of the `page`s of `set_features`).
     */
    case openSettings(from: String, page: String
    )
    /**
     * The device that looks at this one's screen wants its sound (`on`), or no longer: send it with `send_audio_start` and `send_audio`.
     */
    case soundRequested(from: String, on: Bool
    )
    /**
     * A computer wants this phone as its microphone (`on`), or no longer: send it with `send_audio_start` on stream 10 and `send_audio`.
     */
    case micRequested(from: String, on: Bool
    )
    /**
     * A phone asks this computer to be its Bluetooth speaker (`on`), or to stop: answer with `send_bt_speaker_state`.
     */
    case btSpeakerRequested(from: String, on: Bool, name: String
    )
    /**
     * The computer answered `request_bt_speaker`, or its Bluetooth link with this phone ended.
     */
    case btSpeakerState(from: String, on: Bool, error: String
    )
    case input(from: String, input: TandemInput
    )
    case hotspot(from: String, hotspot: TandemHotspot
    )
    /**
     * The other device wants a picture. Answer with `send_files` and origin `Capture { request: id }`,
     * or with `cancel_capture`.
     */
    case captureRequested(from: String, id: UInt64, kind: TandemCaptureKind
    )
    case captureCancelled(from: String, id: UInt64, why: TandemCaptureWhy
    )
    case mediaPlayers(from: String, players: [TandemMediaPlayer]
    )
    case mediaArt(from: String, key: UInt64, jpeg: Data
    )
    /**
     * `action` is None for a command this version does not know.
     */
    case mediaCommand(from: String, player: String, action: TandemMediaAction?, positionMs: UInt64?
    )
    /**
     * The other device is about to send its sound: 16 bit signed samples, interleaved.
     */
    case audioStart(from: String, stream: UInt8, sampleRate: UInt32, channels: UInt8
    )
    case audioStop(from: String, stream: UInt8
    )
    /**
     * Another device asks for the screen or the camera of this one. The same news as `TandemMediaHost.on_request`.
     */
    case mediaRequested(from: String, request: TandemMediaRequest, preApproved: Bool
    )
    case mediaStarted(peer: String, session: UInt64, kind: TandemMediaKind, role: TandemMediaRole
    )
    case mediaEnded(peer: String, session: UInt64, kind: TandemMediaKind, role: TandemMediaRole, reason: TandemMediaEnd
    )
    /**
     * The bitrate the encoder of a host session should move to.
     */
    case mediaBitrate(peer: String, session: UInt64, bitsPerSecond: UInt32
    )
    case mediaQuality(peer: String, session: UInt64, poor: Bool
    )
    /**
     * The other device is ready to show its screen or camera and asks this one to look. Answer with `media_request`.
     */
    case mediaOffered(from: String, kind: TandemMediaKind, facing: TandemMediaFacing, extend: Bool
    )
    /**
     * The pointer of the other computer goes over to this one, or comes back.
     */
    case pointerShare(from: String, msg: TandemPointerShare
    )
    /**
     * A device that this one asked to `ring` plays its sound now, or stopped (there, by itself, or because it was asked).
     */
    case ringing(from: String, on: Bool
    )
    /**
     * About the Wi-Fi of the other device: the network it is on, a question for the password of this one's, or the answer.
     */
    case wifi(from: String, msg: TandemWifi
    )
    /**
     * Messages: on a phone a question to answer, on a computer the messages that changed there (see `sms`).
     */
    case sms(from: String, msg: TandemSmsEvent
    )
    /**
     * Audio routing of a call to this Mac or back to the phone.
     */
    case audioRouting(from: String, id: String, audioOnMac: Bool
    )
    /**
     * A Focus was turned on or off on the device `origin` (passed on by `from`): turn this device's own on or off. `name` is what it
     * is called there, empty when that device cannot tell. Only sent while `set_focus_sharing` says this device follows.
     */
    case focus(from: String, origin: String, on: Bool, name: String
    )





}

