    public static func write(_ value: TandemEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .devicesChanged:
            writeInt(&buf, Int32(1))
        
        
        case let .connected(id):
            writeInt(&buf, Int32(2))
