public enum TandemHotspot: Equatable, Hashable {
    
    case request(reason: String
    )
    case state(on: Bool, ssid: String?, clients: UInt8, dataUsed: UInt64?, error: String?
    )
    case stop
    /**
     * The Mac left for another network: off, unless other devices are still on the hotspot.
     */
    case leave





}

#if compiler(>=6)
extension TandemHotspot: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTandemHotspot: FfiConverterRustBuffer {
    typealias SwiftType = TandemHotspot

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TandemHotspot {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .request(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .state(on: try FfiConverterBool.read(from: &buf), ssid: try FfiConverterOptionString.read(from: &buf), clients: try FfiConverterUInt8.read(from: &buf), dataUsed: try FfiConverterOptionUInt64.read(from: &buf), error: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .stop
        
        case 4: return .leave
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TandemHotspot, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .request(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .state(on,ssid,clients,dataUsed,error):
            writeInt(&buf, Int32(2))
            FfiConverterBool.write(on, into: &buf)
            FfiConverterOptionString.write(ssid, into: &buf)
            FfiConverterUInt8.write(clients, into: &buf)
            FfiConverterOptionUInt64.write(dataUsed, into: &buf)
            FfiConverterOptionString.write(error, into: &buf)
            
        
        case .stop:
            writeInt(&buf, Int32(3))
        
        
        case .leave:
            writeInt(&buf, Int32(4))
        
        }
    }
}


