    )
    case scroll(dx: Int16, dy: Int16
    )
    case button(button: UInt8, down: Bool
    )
    case click(button: UInt8, count: UInt8
    )
    case key(code: UInt16, down: Bool, mods: UInt8
    )
    case text(text: String
    )
    case media(key: TandemMediaKey
    )





}

