extension TandemInput: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTandemInput: FfiConverterRustBuffer {
    typealias SwiftType = TandemInput

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TandemInput {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pointer(dx: try FfiConverterInt16.read(from: &buf), dy: try FfiConverterInt16.read(from: &buf)
        )
        
        case 2: return .scroll(dx: try FfiConverterInt16.read(from: &buf), dy: try FfiConverterInt16.read(from: &buf)
        )
        
        case 3: return .button(button: try FfiConverterUInt8.read(from: &buf), down: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .click(button: try FfiConverterUInt8.read(from: &buf), count: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 5: return .key(code: try FfiConverterUInt16.read(from: &buf), down: try FfiConverterBool.read(from: &buf), mods: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 6: return .text(text: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .media(key: try FfiConverterTypeTandemMediaKey.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TandemInput, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .pointer(dx,dy):
            writeInt(&buf, Int32(1))
            FfiConverterInt16.write(dx, into: &buf)
            FfiConverterInt16.write(dy, into: &buf)
            
        
        case let .scroll(dx,dy):
            writeInt(&buf, Int32(2))
            FfiConverterInt16.write(dx, into: &buf)
            FfiConverterInt16.write(dy, into: &buf)
            
        
        case let .button(button,down):
            writeInt(&buf, Int32(3))
            FfiConverterUInt8.write(button, into: &buf)
            FfiConverterBool.write(down, into: &buf)
            
        
        case let .click(button,count):
            writeInt(&buf, Int32(4))
            FfiConverterUInt8.write(button, into: &buf)
            FfiConverterUInt8.write(count, into: &buf)
            
        
        case let .key(code,down,mods):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterBool.write(down, into: &buf)
            FfiConverterUInt8.write(mods, into: &buf)
            
        
        case let .text(text):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .media(key):
            writeInt(&buf, Int32(7))
            FfiConverterTypeTandemMediaKey.write(key, into: &buf)
            
        }
    }
}


