 */

public enum TandemMediaEnd: Equatable, Hashable {
    
    /**
     * A person stopped it.
     */
    case ended
    case declined
    /**
     * The policy of the host says never.
     */
    case policy
    case busy
    /**
     * The kind or the codec is not something the host can do.
     */
    case unsupported
    /**
     * The host would, but cannot: no permission to capture, no camera.
     */
    case unavailable
    case timeout
    /**
     * The same device started a new session of this kind.
     */
    case replaced
    case unknownSession
    /**
     * The other device was gone for longer than the grace period, or restarted.
     */
    case peerGone
    /**
     * The host is locked, so there is nothing to show until someone unlocks it there.
