public enum TandemMediaInput: Equatable, Hashable {
    
    /**
     * A fraction of the streamed picture, 0.0 to 1.0, the top left corner is the origin.
     */
    case pointerAbs(x: Float, y: Float
    )
    case pointerRel(dx: Int16, dy: Int16
    )
    /**
     * 0 primary, 1 secondary, 2 middle, 3 back, 4 forward. `clicks` is the count of this press, 0 counts as 1.
     */
    case button(button: UInt8, down: Bool, clicks: UInt8
    )
    /**
     * Pixels of the streamed picture, in the natural direction: the content follows the fingers.
     */
    case scroll(dx: Int16, dy: Int16
    )
    /**
     * `code` is the USB HID usage on the Keyboard page, `mods` is 1 shift, 2 control, 4 alt, 8 meta, 16 caps lock.
     */
    case key(code: UInt32, down: Bool, mods: UInt16, text: String
    )
    /**
     * A piece of text that was committed. Not the clipboard.
     */
    case text(text: String
    )
    /**
     * The person confirmed it is them; only sent after the host offered to unlock.
     */
    case unlock





}

#if compiler(>=6)
extension TandemMediaInput: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTandemMediaInput: FfiConverterRustBuffer {
    typealias SwiftType = TandemMediaInput

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TandemMediaInput {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pointerAbs(x: try FfiConverterFloat.read(from: &buf), y: try FfiConverterFloat.read(from: &buf)
        )
        
        case 2: return .pointerRel(dx: try FfiConverterInt16.read(from: &buf), dy: try FfiConverterInt16.read(from: &buf)
        )
        
        case 3: return .button(button: try FfiConverterUInt8.read(from: &buf), down: try FfiConverterBool.read(from: &buf), clicks: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 4: return .scroll(dx: try FfiConverterInt16.read(from: &buf), dy: try FfiConverterInt16.read(from: &buf)
        )
        
        case 5: return .key(code: try FfiConverterUInt32.read(from: &buf), down: try FfiConverterBool.read(from: &buf), mods: try FfiConverterUInt16.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .text(text: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .unlock
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TandemMediaInput, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .pointerAbs(x,y):
            writeInt(&buf, Int32(1))
            FfiConverterFloat.write(x, into: &buf)
            FfiConverterFloat.write(y, into: &buf)
            
        
        case let .pointerRel(dx,dy):
            writeInt(&buf, Int32(2))
            FfiConverterInt16.write(dx, into: &buf)
            FfiConverterInt16.write(dy, into: &buf)
            
        
        case let .button(button,down,clicks):
            writeInt(&buf, Int32(3))
            FfiConverterUInt8.write(button, into: &buf)
            FfiConverterBool.write(down, into: &buf)
            FfiConverterUInt8.write(clicks, into: &buf)
            
        
        case let .scroll(dx,dy):
            writeInt(&buf, Int32(4))
            FfiConverterInt16.write(dx, into: &buf)
            FfiConverterInt16.write(dy, into: &buf)
            
        
        case let .key(code,down,mods,text):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(code, into: &buf)
            FfiConverterBool.write(down, into: &buf)
            FfiConverterUInt16.write(mods, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .text(text):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(text, into: &buf)
            
        
        case .unlock:
            writeInt(&buf, Int32(7))
        
        }
    }
}


