    typealias SwiftType = TandemSmsRequest

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TandemSmsRequest {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .listConversations(before: try FfiConverterUInt64.read(from: &buf), limit: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 2: return .listMessages(thread: try FfiConverterUInt64.read(from: &buf), before: try FfiConverterUInt64.read(from: &buf), limit: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 3: return .send(to: try FfiConverterSequenceString.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .findContacts(query: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .picture(part: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 6: return .listContacts(after: try FfiConverterUInt64.read(from: &buf), limit: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TandemSmsRequest, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .listConversations(before,limit):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(before, into: &buf)
            FfiConverterUInt32.write(limit, into: &buf)
            
        
        case let .listMessages(thread,before,limit):
