private let UNIFFI_RUST_FUTURE_POLL_READY: Int8 = 0
private let UNIFFI_RUST_FUTURE_POLL_WAKE: Int8 = 1

fileprivate let uniffiContinuationHandleMap = UniffiHandleMap<UnsafeContinuation<Int8, Never>>()

fileprivate func uniffiRustCallAsync<F, T>(
    rustFutureFunc: () -> UInt64,
    pollFunc: (UInt64, @escaping UniffiRustFutureContinuationCallback, UInt64) -> (),
    completeFunc: (UInt64, UnsafeMutablePointer<RustCallStatus>) -> F,
    freeFunc: (UInt64) -> (),
    liftFunc: (F) throws -> T,
    errorHandler: ((RustBuffer) throws -> Swift.Error)?
) async throws -> T {
    // Make sure to call the ensure init function since future creation doesn't have a
    // RustCallStatus param, so doesn't use makeRustCall()
    uniffiEnsureTandemCoreInitialized()
    let rustFuture = rustFutureFunc()
    defer {
        freeFunc(rustFuture)
    }
    var pollResult: Int8;
    repeat {
        pollResult = await withUnsafeContinuation {
            pollFunc(
                rustFuture,
                { handle, pollResult in
                    uniffiFutureContinuationCallback(handle: handle, pollResult: pollResult)
                },
                uniffiContinuationHandleMap.insert(obj: $0)
            )
        }
    } while pollResult != UNIFFI_RUST_FUTURE_POLL_READY

    return try liftFunc(makeRustCall(
        { completeFunc(rustFuture, $0) },
        errorHandler: errorHandler
    ))
}

// Callback handlers for an async calls.  These are invoked by Rust when the future is ready.  They
// lift the return value or error and resume the suspended function.
fileprivate func uniffiFutureContinuationCallback(handle: UInt64, pollResult: Int8) {
    if let continuation = try? uniffiContinuationHandleMap.remove(handle: handle) {
        continuation.resume(returning: pollResult)
    } else {
        print("uniffiFutureContinuationCallback invalid handle")
    }
}
/**
 * The pointer comes back from a screen: where that is along the edge of the main screen.
 */
public func layoutBack(mainLen: Int32, placement: TandemPlacement, width: Int32, height: Int32, along: Float) -> Int32  {
    return try!  FfiConverterInt32.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_tandem_core_fn_func_layout_back(
        FfiConverterInt32.lower(mainLen),
        FfiConverterTypeTandemPlacement_lower(placement),
        FfiConverterInt32.lower(width),
        FfiConverterInt32.lower(height),
        FfiConverterFloat.lower(along),uniffiCallStatus
    )
})
}
/**
 * The pointer runs into `edge` of the main screen at `position` along it: which screen is there, if any.
 */
public func layoutCross(edge: TandemEdge, position: Int32, list: [TandemNeighbour]) -> TandemCrossing?  {
    return try!  FfiConverterOptionTypeTandemCrossing.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_tandem_core_fn_func_layout_cross(
        FfiConverterTypeTandemEdge_lower(edge),
        FfiConverterInt32.lower(position),
        FfiConverterSequenceTypeTandemNeighbour.lower(list),uniffiCallStatus
    )
})
}
/**
 * A box was dragged here: the place it snaps to, or nothing when it is too far from the main screen.
 */
public func layoutPlace(mainWidth: Int32, mainHeight: Int32, dragged: TandemRect, others: [TandemNeighbour], snap: Int32) -> TandemPlacement?  {
    return try!  FfiConverterOptionTypeTandemPlacement.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_tandem_core_fn_func_layout_place(
        FfiConverterInt32.lower(mainWidth),
        FfiConverterInt32.lower(mainHeight),
        FfiConverterTypeTandemRect_lower(dragged),
        FfiConverterSequenceTypeTandemNeighbour.lower(others),
        FfiConverterInt32.lower(snap),uniffiCallStatus
    )
})
